<script setup lang="ts">
const uni = (globalThis as any).uni;
import { onShow } from '@dcloudio/uni-app';import { ref } from 'vue';import { api,hasSession } from '../../services/api';
import { label } from '../../services/display';
const items=ref<any[]>([]);const loading=ref(true);const filter=ref('');
async function load(){if(!hasSession())return uni.reLaunch({url:'/pages/login/login'});loading.value=true;try{const r:any=await api(`/me/tasks${filter.value?`?status=${filter.value}`:''}`);items.value=r.items??[];}catch(e:any){uni.showToast({title:e.message,icon:'none'});}finally{loading.value=false;}}
function change(v:string){filter.value=v;load();}onShow(load);
</script>
<template><view class="page"><view class="filters"><text :class="{active:!filter}" @tap="change('')">全部</text><text :class="{active:filter==='PENDING'}" @tap="change('PENDING')">待完成</text><text :class="{active:filter==='RETURNED'}" @tap="change('RETURNED')">退回补充</text><text :class="{active:filter==='SUBMITTED'}" @tap="change('SUBMITTED')">待审核</text></view><view v-if="loading" class="empty">正在加载…</view><view v-else-if="!items.length" class="empty">暂无任务</view><view v-for="item in items" :key="item.id" class="card row" @tap="uni.navigateTo({url:`/pages/tasks/detail?id=${item.id}`})"><view class="mode">{{item.completionMode==='SIMPLE'?'简单':'审核'}}</view><view class="content"><text class="title">{{item.title}}</text><text :class="['status',item.derivedStatus?.startsWith('OVERDUE')?'danger':'muted']">{{ label(item.derivedStatus) }} · {{new Date(item.deadlineAt).toLocaleString('zh-CN')}}</text></view><text class="arrow">›</text></view></view></template>
<style scoped>.filters{display:flex;gap:14rpx;margin-bottom:25rpx;overflow:auto}.filters text{padding:14rpx 22rpx;white-space:nowrap;color:#667f84;border-radius:24rpx;background:#fff}.filters .active{color:#fff;background:#007f95}.row{display:flex;align-items:center}.mode{padding:10rpx 14rpx;color:#b76632;font-size:21rpx;border-radius:12rpx;background:#fff0e6}.content{flex:1;margin-left:20rpx}.title,.status{display:block}.title{margin-bottom:10rpx;font-weight:700}.status{font-size:22rpx}.arrow{font-size:42rpx;color:#9aaeb2}</style>
